function trasforma(input){
  var n = function(s){ return parseFloat(String(s).replace(/\./g, '').replace(',', '.')); };
  var by = {};
  input.Righe.forEach(function(r){ var a = parseInt(r.Aliquota, 10); by[a] = Math.round(((by[a] || 0) + n(r.Importo)) * 100) / 100; });
  var riep = Object.keys(by).map(Number).sort(function(a, b){ return b - a; }).map(function(a){
    return { aliquota: a, imponibile: by[a], iva: Math.round(by[a] * a) / 100 };
  });
  var tot = riep.reduce(function(s, z){ return s + z.imponibile + z.iva; }, 0);
  return { riepilogo: riep, totale: Math.round(tot * 100) / 100 };
}

ref_py:
def trasforma(campi):
    n = lambda s: float(str(s).replace('.', '').replace(',', '.'))
    by = {}
    for r in campi['Righe']:
        a = int(r['Aliquota'].rstrip('%'))
        by[a] = round(by.get(a, 0) + n(r['Importo']), 2)
    riep = [{'aliquota': a, 'imponibile': by[a], 'iva': round(by[a] * a / 100, 2)} for a in sorted(by, reverse=True)]
    return {'riepilogo': riep, 'totale': round(sum(z['imponibile'] + z['iva'] for z in riep), 2)}
